static int create_parent_directories(const char *path) {
    char *path_copy = strdup(path);
    if (!path_copy)
        return -ENOMEM;

    char *p = path_copy;
    while ((p = strchr(p, '/'))) {
        if (p != path_copy && p > path_copy && *(p - 1) == '/')
            p++;
        else
            p++;
        *p = '\0';
        if (strcmp(path_copy, ".") == 0 || strcmp(path_copy, "/") == 0) {
            *p = '/';
            continue;
        }
        if (mkdir(path_copy, 0755) && errno != EEXIST) {
            free(path_copy);
            return -errno;
        }
    }
    *p = '\0';
    free(path_copy);
    return 0;
}

int create_or_update_file(const char *path, bool parents, usec_t stamp, uid_t uid, gid_t gid, mode_t mode) {
    int fd;
    int r = 0;

    if (!path) {
        errno = EINVAL;
        return -errno;
    }

    if (parents) {
        r = create_parent_directories(path);
        if (r < 0)
            return r;
    }

    fd = open(path, O_CREAT | O_WRONLY | O_TRUNC, mode ? mode : 0644);
    if (fd < 0) {
        r = -errno;
        return r;
    }

    if (uid != (uid_t)-1 && gid != (gid_t)-1) {
        if (chown(path, uid, gid) < 0) {
            r = -errno;
            close(fd);
            return r;
        }
    }

    if (utimes(path, NULL) < 0) {
        r = -errno;
        close(fd);
        return r;
    }

    close(fd);
    return 0;
}

int create_or_update_file(const char *path, bool parents, usec_t stamp, uid_t uid, gid_t gid, mode_t mode) {
    int fd = -1;
    struct timespec times[2];

    // Validate path
    if (!path || *path == '\0') {
        return -EINVAL;
    }

    // Set default mode if invalid
    if (mode == 0 || (mode & S_IFMT) != 0) {
        mode = S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH; // 0644
    }

    // Create parent directories if requested
    if (parents) {
        int r = mkdir_parents(path, 0755);
        if (r < 0) {
            return r;
        }
    }

    // Open the file for writing (create if necessary)
    fd = open(path, O_CREAT | O_WRONLY | O_TRUNC, mode);
    if (fd < 0) {
        return -errno;
    }

    // Set file ownership
    if (chown(path, uid, gid) < 0) {
        int saved_errno = -errno;
        close(fd);
        return saved_errno;
    }

    // Set file timestamps
    times[0].tv_nsec = stamp;
    times[1].tv_nsec = stamp;
    if (futimens(fd, times) < 0) {
        int saved_errno = -errno;
        close(fd);
        return saved_errno;
    }

    // Close the file
    if (close(fd) < 0) {
        return -errno;
    }

    return 0;
}

