#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>

int create_or_update_file(const char *path, bool parents, usec_t stamp, uid_t uid, gid_t gid, mode_t mode) {
    int fd = -1;
    mode_t default_mode = S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH; // 0644

    if (!path || path[0] == '\0') {
        return -EINVAL;
    }

    if (parents) {
        // Use umask to preserve default_mode
        mode_t old_umask = umask(0);
        if (mkdir_p(path, default_mode) < 0) {
            umask(old_umask);
            return -errno;
        }
        umask(old_umask);
    }

    fd = open(path, O_CREAT | O_WRONLY | O_TRUNC, mode ? mode : default_mode);
    if (fd < 0) {
        return -errno;
    }

    if (mode) {
        if (fchmod(fd, mode) < 0) {
            int error = -errno;
            close(fd);
            return error;
        }
    }

    if (chown(path, uid, gid) < 0) {
        int error = -errno;
        close(fd);
        return error;
    }

    struct timespec times[2];
    times[0].tv_sec = stamp / 1000000;
    times[0].tv_nsec = (stamp % 1000000) * 1000;
    times[1] = times[0];

    if (utimensat(AT_FDCWD, path, times, 0) < 0) {
        int error = -errno;
        close(fd);
        return error;
    }

    close(fd);
    return 0;
}
